21	const NONCE_BYTES: usize = 32;
22	const SIGNATURE_BYTES: usize = 64;
23	const REJECTION_MESSAGE: &str = "sovereign session proof rejected";
24	
25	#[derive(Deserialize)]
26	#[serde(rename_all = "camelCase", deny_unknown_fields)]
27	pub struct SovereignSessionRequest {
28	    did: String,
29	    signing_key: String,
30	    timestamp: i64,
31	    nonce: String,
