239	/// `POST /oauth/authorize/approve` — verify a device-key-signed approve/deny envelope against the
240	/// account's authoritative PLC rotation set and terminate the request accordingly.
241	pub async fn post_authorization_approve(
242	    State(state): State<AppState>,
243	    Json(request): Json<ApprovalRequest>,
244	) -> Result<Json<ApprovalResponse>, ApiError> {
245	    // 1. Cheap syntactic gates before any DB or network work.
246	    let signature = decode_canonical_base64url(&request.signature, SIGNATURE_BYTES)
247	        .and_then(|bytes| <[u8; SIGNATURE_BYTES]>::try_from(bytes).ok())
248	        .ok_or_else(approval_rejected)?;
249	    if decode_canonical_base64url(&request.nonce, NONCE_BYTES).is_none() {
250	        return Err(approval_rejected());
251	    }
252	    if !is_plc_did(&request.did) {
253	        return Err(approval_rejected());
254	    }
255	    let approve = match request.decision.as_str() {
256	        crypto::OAUTH_CONSENT_DECISION_APPROVE => true,
257	        crypto::OAUTH_CONSENT_DECISION_DENY => false,
258	        _ => return Err(approval_rejected()),
259	    };
260	    let now = crate::time::unix_now_secs();
261	    if now.abs_diff(request.timestamp) > SOVEREIGN_TIMESTAMP_WINDOW_SECS as u64 {
262	        return Err(approval_rejected());
263	    }
264	
265	    // 2. Load the pending request; it must be currently approvable.
266	    let pending = get_pending_by_request_id(&state.db, &request.request_id)
267	        .await?
268	        .filter(|p| p.status == "pending" && !p.is_expired)
269	        .ok_or_else(not_approvable)?;
270	
271	    // 3. Account binding: a pre-bound login_hint must match the approving DID; otherwise the wallet
272	    //    binds its own DID here (like the agent claim confirm). Either way the DID must be a local
273	    //    active account so the authorization code can be issued against it.
274	    if let Some(hint) = pending.login_hint.as_deref() {
275	        if hint != request.did {
276	            return Err(approval_rejected());
277	        }
278	    }
279	    if !crate::db::accounts::active_local_account_exists(&state.db, &request.did).await? {
280	        return Err(approval_rejected());
281	    }
282	
283	    // 4. The granted scope the wallet signed over is the verbatim `granted_scope` string (empty for
284	    //    a denial); the stored set is that, reduced to what was actually requested.
285	    let signed_scope = if approve {
286	        request.granted_scope.as_str()
287	    } else {
288	        ""
289	    };
290	    let stored_scope = reduce_granted_scope(&pending.requested_scope, signed_scope);
291	
292	    // 5. Verify the envelope signature, then confirm the signing key is in the account's
293	    //    authoritative current PLC rotation set (never the cached DID doc). Signature first, so an
294	    //    invalid signature never triggers the outbound PLC fetch.
295	    let server_did = state.config.resolve_server_did();
296	    let envelope = crypto::encode_oauth_consent_envelope(
297	        &server_did,
298	        &request.did,
299	        &request.signing_key,
300	        &request.request_id,
301	        &pending.client_id,
302	        &request.decision,
303	        signed_scope,
304	        request.timestamp,
305	        &request.nonce,
306	    );
307	    let signing_key = crypto::DidKeyUri(request.signing_key.clone());
308	    crypto::verify_did_key_signature(&signing_key, &envelope, &signature)
309	        .map_err(|_| approval_rejected())?;
310	
311	    let plc = fetch_current_plc_state(
312	        &state.http_client,
313	        &state.config.plc_directory_url,
314	        &request.did,
315	    )
316	    .await?;
317	    if !plc.rotation_keys.iter().any(|k| k == &request.signing_key) {
318	        return Err(approval_rejected());
319	    }
320	
321	    // 6. Terminate the request and audit it in one transaction. The guarded UPDATE is the single-use
322	    //    point: a replayed envelope lands on an already-terminal row and wins nothing.
323	    let mut tx = state.db.begin().await.map_err(|e| {
324	        tracing::error!(error = %e, "failed to begin consent approval transaction");
325	        ApiError::new(ErrorCode::InternalError, "failed to record decision")
326	    })?;
327	    let won = if approve {
328	        approve_pending_authorization(&mut *tx, &request.request_id, &request.did, &stored_scope)
329	            .await?
330	    } else {
